{
  "chart_id": "chart-17",
  "issues": [
    {
      "description": "营业收入与两项利润共用纵轴，各期量级比均超过 5 倍。两条利润线和点标记在手机图面上几乎重叠，难以看清标题强调的利润回落。",
      "experience_ids": ["team-v2-2.5"],
      "severity": "high",
      "location": "折线图绘图区",
      "suggestion": "拆成上下两图：上图显示营业收入，下图显示两项利润。共用对齐的期间标签，各图分别标注单位并使用独立纵轴。",
      "evidence": [
        "PNG 与 SVG 的 12 个点标签均与数据数值一致，点位与 0–12 的线性刻度一致；0.8 显示为 0.80，数值未变。",
        "按图中共同单位，2023H1 至 2026H1 营业收入除以归母净利润依次约为 7.12、9.48、8.70、10.36 倍，除以扣非净利润依次约为 7.63、10.19、8.94、10.77 倍。",
        "营业收入从 2024H1 起连续两年上升；两项利润均在 2026H1 较 2025H1 回落。"
      ]
    },
    {
      "description": "图表区底部到脚注分隔线的间距为 64 CSS px，比规范要求多 40 px。",
      "experience_ids": ["team-v2-1.4"],
      "severity": "medium",
      "location": "图表区底部至脚注分隔线",
      "suggestion": "将页脚上外边距改为 24px，并以图表容器底边到分隔线复核。",
      "evidence": [
        "SVG 为块级元素，页脚内联样式为 margin-top: 64px，分隔线由页脚的 border-top 绘制。",
        "PNG 中图表区与脚注分隔线之间有明显留白。"
      ]
    },
    {
      "description": "单位行“亿元”的左边缘比纵轴刻度文字的最左边缘更靠左。",
      "experience_ids": ["team-v2-2.4"],
      "severity": "low",
      "location": "纵轴上方单位行",
      "suggestion": "保留单位行在纵轴上方，将其左边缘对齐到最靠左的刻度文字边缘。",
      "evidence": [
        "PNG 中“亿元”左缘位于刻度“12”左缘的左侧。",
        "SVG 单位行从 x=0 起排，刻度文字在 x=15 处右对齐，图面上两者左缘不重合。"
      ]
    },
    {
      "description": "12 个点标签均重复附加“亿”，纵轴上方已有“亿元”单位行。",
      "experience_ids": ["team-v2-3.2"],
      "severity": "low",
      "location": "三条折线的数据点标签",
      "suggestion": "点标签只保留两位小数的数值，例如“10.88”和“0.80”，单位集中写在对应单位行。",
      "evidence": [
        "PNG 和 SVG 均显示“10.88亿”“0.80亿”等标签，单位行均写为“亿元”。"
      ]
    }
  ],
  "observations": [
    {
      "description": "外层画布与白色内框的宽度口径待确认。",
      "evidence": [
        "用途说明写卡片宽 375pt；源码外层 body 宽 375 CSS px，白色内框左右各有 10 CSS px 外边距，外框宽 355 CSS px，左右内边距各 16 CSS px。",
        "PNG 宽 1125 像素，与源码外层宽度的 3 倍相符。"
      ],
      "reason_unconfirmed": "需确认规范的 375 指外层画布还是白色内框，以及 App 中 CSS px 与 pt 的映射；现有证据不足以判定卡片宽度违规。"
    },
    {
      "description": "图内金额单位明确，输入数据字段未独立注明单位。",
      "evidence": [
        "PNG 和 SVG 统一标示“亿元”，三个金额字段的数值均直接对应图中标签；输入数据只列字段名和数值。"
      ],
      "reason_unconfirmed": "量级比较依据图中声明的共同单位；若需独立验证原始字段是否均以亿元计，需查看字段单位定义。"
    },
    {
      "description": "0.8 显示为 0.80 符合图内两位小数格式，输入精度无法单凭字符串确认。",
      "evidence": [
        "2024H1 扣非净利润的输入为“0.8”，PNG 和 SVG 均显示“0.80亿”。"
      ],
      "reason_unconfirmed": "需由字段精度定义确认输入是否省略末尾零；现有材料只能确认数值相等和显示格式一致。"
    }
  ]
}
